SELECT
    $q0[0].v AS min_ref_paperid,
    $q1[0].v AS author,
    $q2[0].v AS newsfeed
LET
    $q0 = (SELECT MIN(paperid) AS v FROM Papers WHERE paperid IN (SELECT cited_paperid FROM PaperReferences WHERE citing_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT cited_paperid FROM PaperReferences WHERE citing_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT cited_paperid FROM PaperReferences WHERE citing_paperid IN (SELECT paperid FROM Papers WHERE paperid = 'W4235901390' AND paperid IN (SELECT paperid FROM Authors_Paper WHERE authorid IN (SELECT authorid FROM Authors_Gender)) AND paperid IN (SELECT paperid FROM link_newsfeed WHERE newsfeed_id IN (SELECT newsfeed_id FROM Newsfeed_Metadata))))))))),
    $q1 = (SELECT MIN(authorid) AS v FROM Authors_Gender WHERE authorid IN (SELECT authorid FROM Authors_Paper WHERE paperid IN (SELECT paperid FROM Papers WHERE paperid = 'W4235901390' AND paperid IN (SELECT paperid FROM link_newsfeed WHERE newsfeed_id IN (SELECT newsfeed_id FROM Newsfeed_Metadata)) AND paperid IN (SELECT citing_paperid FROM PaperReferences WHERE cited_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT citing_paperid FROM PaperReferences WHERE cited_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT citing_paperid FROM PaperReferences)))))))),
    $q2 = (SELECT MIN(newsfeed_id) AS v FROM Newsfeed_Metadata WHERE newsfeed_id IN (SELECT newsfeed_id FROM link_newsfeed WHERE paperid IN (SELECT paperid FROM Papers WHERE paperid = 'W4235901390' AND paperid IN (SELECT paperid FROM Authors_Paper WHERE authorid IN (SELECT authorid FROM Authors_Gender)) AND paperid IN (SELECT citing_paperid FROM PaperReferences WHERE cited_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT citing_paperid FROM PaperReferences WHERE cited_paperid IN (SELECT paperid FROM Papers WHERE paperid IN (SELECT citing_paperid FROM PaperReferences))))))));
